```python
# Cache pincode lookups for fast auto-suggest
async def get_cached_pincode_localities(pincode: str):
    cache_key = f"localities:{pincode}"
    cached = await redis.get(cache_key)
    if cached:
        return json.loads(cached)

    localities = await db.query(Locality).filter(...).all()
    await redis.setex(cache_key, 3600, json.dumps(localities))  # 1 hour cache
    return localities
