**5. Offline Mode Support:**
```dart
// core/services/sync_service.dart
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:hive/hive.dart';

class SyncService {
  final Box _pendingActionsBox = Hive.box('pending_actions');

  Future<void> queueAction(PendingAction action) async {
    await _pendingActionsBox.add(action.toJson());
  }

  Future<void> syncPendingActions() async {
    final connectivity = await Connectivity().checkConnectivity();
    if (connectivity != ConnectivityResult.none) {
      final pending = _pendingActionsBox.values.toList();
      for (var action in pending) {
        await _processAction(action);
      }
      await _pendingActionsBox.clear();
    }
  }
}
```

